<div class="modal-header"><div><h2 class="modal-title" id="sales-modal-title">Sale details</h2><p class="modal-subtitle"><?= e($sale['sale_number']) ?> · <?= e((new DateTimeImmutable($sale['sold_at']))->format('j M Y, g:i A')) ?></p></div><button class="btn-close" type="button" data-bs-dismiss="modal" aria-label="Close"></button></div>
<div class="modal-body sale-details-body">
    <div class="sale-modal-customer"><div><span class="detail-label">Customer</span><h3><?= e($sale['customer_name']??'Walk-in customer') ?></h3><?php if ($sale['due_date']): ?><p>Due <?= e((new DateTimeImmutable($sale['due_date']))->format('j M Y')) ?></p><?php endif; ?></div><span class="payment-badge status-<?= e(sale_badge($sale)) ?>"><?= e(sale_status($sale)) ?></span></div>
    <section class="sale-modal-section"><h3>Items purchased</h3><div class="sale-detail-items">
        <?php foreach ($sale['items'] as $item): ?><article class="sale-detail-item"><div><strong><?= e($item['product_name_snapshot']) ?></strong><p><?= e(rtrim(rtrim($item['quantity'],'0'),'.')) ?> × <?= e(sale_money($item['unit_price'])) ?></p></div><strong><?= e(sale_money(sale_round(bcmul($item['quantity'],$item['unit_price'],5)))) ?></strong></article><?php endforeach; ?>
    </div></section>
    <section class="sale-modal-section"><h3>Sale total</h3><dl class="sale-total-list"><div><dt>Subtotal</dt><dd><?= e(sale_money($sale['subtotal'])) ?></dd></div><div><dt>Discount<?= $sale['discount_type']==='percent'?' ('.e($sale['discount_value']).'%)':'' ?></dt><dd><?= e(sale_money(bcsub($sale['subtotal'],$sale['net_sale'],2))) ?></dd></div><div class="sale-grand-total"><dt>Total sale amount</dt><dd><?= e(sale_money($sale['net_sale'])) ?></dd></div><div><dt>Amount paid, less refunds</dt><dd><?= e(sale_money($sale['total_paid'])) ?></dd></div><div><dt><?= $sale['sale_status']==='posted'?'Outstanding balance':'Current debt' ?></dt><dd><?= e(sale_money($sale['sale_status']==='posted'?$sale['balance_due']:'0.00')) ?></dd></div></dl></section>
    <section class="sale-modal-section"><h3>Payment history</h3><?php if (!$sale['payments']): ?><p class="sale-modal-note">No payments recorded.</p><?php endif; ?>
        <?php foreach ($sale['payments'] as $payment): ?><article class="sale-detail-item"><div><strong><?= e($payment['method_name']) ?> · <?= $payment['payment_kind']==='refund'?'Refund':'Payment' ?></strong><p><?= e((new DateTimeImmutable($payment['paid_at']))->format('j M Y, g:i A')) ?></p><?php if ($payment['provider_name']): ?><p><?= e($payment['provider_name']) ?></p><?php endif; ?><?php if ($payment['reference_number']): ?><p><?= e($payment['reference_number']) ?></p><?php endif; ?></div><strong class="<?= $payment['payment_kind']==='refund'?'amount-negative':'' ?>"><?= $payment['payment_kind']==='refund'?'−':'' ?><?= e(sale_money($payment['amount'])) ?></strong></article><?php endforeach; ?>
    </section>
    <?php if ($sale['notes']): ?><section class="sale-modal-section"><h3>Notes</h3><p class="sale-notes"><?= nl2br(e($sale['notes'])) ?></p></section><?php endif; ?>
    <?php if ($sale['sale_status']==='draft'): ?><p class="sale-modal-note">This draft is not included in sales or customer debt until completed.</p><?php endif; ?>
    <?php if ($sale['sale_status']==='void'): ?><p class="sale-modal-note"><strong>Void reason:</strong> <?= e($sale['void_reason']) ?></p><?php endif; ?>
</div>
<div class="modal-footer"><button class="btn btn-outline-secondary" type="button" data-bs-dismiss="modal">Close</button></div>
